.dkdone{min-height:16px!important;margin:8px 0 0!important}.dktargets{margin:4px 0 10px!important}.dktargets .dkp{padding:9px 16px!important}
.dkreset{padding:10px 28px!important;font-size:16px!important;border-radius:14px!important}.dktotal{margin-top:12px!important;font-size:14px!important}
.dk{padding-bottom:18px!important}

/* even smaller tasbeeh */
.dk{padding:12px 12px 14px!important}
.dkring{width:min(150px,42vw)!important;padding:4px!important}
.dktap small{font-size:10px!important;letter-spacing:.24em!important}.dktap b{font-size:clamp(32px,10vw,40px)!important;margin-top:2px!important}
.dkar{font-size:clamp(26px,7.5vw,32px)!important;margin:2px 0 6px!important;line-height:1.4!important}
.dktabs{margin-bottom:10px!important;padding:4px!important}.dktabs button{padding:10px 4px!important;font-size:13px!important}
.dkpills{gap:6px!important}.dkp{padding:7px 13px!important;font-size:13px!important}
.dkdone{min-height:12px!important;margin:5px 0 0!important;font-size:12px!important}.dktargets{margin:2px 0 8px!important;gap:6px!important}.dktargets .dkp{padding:7px 14px!important}
.dkreset{padding:8px 24px!important;font-size:14px!important;border-radius:12px!important}.dktotal{margin-top:9px!important;font-size:13px!important}

/* arabic text: clear gap from pills above */
.dkpills{margin-bottom:12px!important}
