location.href="mailto:officialaltaqwa@gmail.com?subject="+encodeURIComponent("AL-TAQWA admission enquiry: "+f.get("course"))+"&body="+encodeURIComponent(msg);
toast("Opening email draft. Press send to deliver your enquiry!");
});

document.getElementById("contactForm").addEventListener("submit",e=>{
