const tCats=["All","Qur'an & Tajweed","Islamic Studies","Arabic & Urdu","Workshops & Short Courses"];
document.getElementById("tFilters").innerHTML=tCats.map(n=>`<button class="tchip${n===tFilter?" on":""}" data-tf="${n}">${n}</button>`).join("");
const list=teachers.filter(t=>tFilter==="All"||t.category===tFilter||t.courses.some(c=>c.toLowerCase().includes(tFilter.toLowerCase())));
document.getElementById("tGrid").innerHTML=list.length?list.map(t=>`<article class="tcard"><div class="tavatar">${t.initials}</div><div><h3>${t.name}</h3><p class="trole">${t.role}</p></div><div class="tmeta">${t.courses.map(c=>`<span>${c.split("—")[0].split("(")[0].trim()}</span>`).join("")}<span>${t.lang}</span></div><p class="tbio">${t.bio}</p><p class="trole">${t.quals} · ${t.exp}</p><button class="tenq" data-enquire="${t.courses[0]}">Enquire for this course ↗</button></article>`).join(""):'<p>No teachers listed for this category yet.</p>';
}

document.getElementById("tFilters").addEventListener("click",e=>{const b=e.target.closest("[data-tf]");if(b){tFilter=b.dataset.tf;renderTeachers()}});
renderTeachers();

/* ===== HOME SLIDERS (courses + teachers) ===== */
function teacherCard(t){return `<article class="tcard"><div class="tavatar">${t.initials}</div><div><h3>${t.name}</h3><p class="trole">${t.role}</p></div><div class="tmeta">${t.courses.map(c=>`<span>${c.split("—")[0].split("(")[0].trim()}</span>`).join("")}<span>${t.lang}</span></div><p class="tbio">${t.bio}</p><p class="trole">${t.quals} · ${t.exp}</p><button class="tenq" data-enquire="${t.courses[0]}">Enquire for this course ↗</button></article>`}
document.getElementById("homeTeachers").innerHTML=teachers.map(teacherCard).join("");

function initSlider(root){
const track=root.querySelector(".strack"),prev=root.querySelector(".prev"),next=root.querySelector(".next"),dots=root.querySelector(".sdots");
let timer=null;
const items=()=>[...track.children];
const step=()=>{const f=track.children[0];return f?f.getBoundingClientRect().width+18:1};
const pages=()=>{const per=Math.max(1,Math.round(track.clientWidth/step()));return Math.max(1,items().length-per+1)};
function buildDots(){dots.innerHTML="";for(let i=0;i<pages();i++){const b=document.createElement("button");b.setAttribute("aria-label","Go to slide "+(i+1));b.onclick=()=>{track.scrollTo({left:i*step()});restart()};dots.appendChild(b)}update()}
function update(){const i=Math.min(pages()-1,Math.round(track.scrollLeft/step()));[...dots.children].forEach((d,k)=>d.classList.toggle("on",k===i));prev.disabled=track.scrollLeft<4;next.disabled=track.scrollLeft+track.clientWidth>=track.scrollWidth-4}
function go(d){const end=track.scrollLeft+track.clientWidth>=track.scrollWidth-4;if(d>0&&end)track.scrollTo({left:0});else track.scrollBy({left:d*step()})}
prev.onclick=()=>{go(-1);restart()};next.onclick=()=>{go(1);restart()};track.addEventListener("scroll",()=>requestAnimationFrame(update),{passive:true});
function start(){if(matchMedia("(prefers-reduced-motion: reduce)").matches)return;stop();timer=setInterval(()=>{if(document.getElementById("home").classList.contains("active"))go(1)},5000)}
function stop(){clearInterval(timer)}function restart(){stop();start()}
root.addEventListener("mouseenter",stop);root.addEventListener("mouseleave",start);root.addEventListener("touchstart",stop,{passive:true});root.addEventListener("touchend",start,{passive:true});
window.addEventListener("resize",buildDots);window.addEventListener("load",buildDots);new MutationObserver(buildDots).observe(track,{childList:true});buildDots();start()}
document.querySelectorAll("[data-slider]").forEach(initSlider);

document.getElementById("year").textContent=new Date().getFullYear();
renderCourses();
</script>

<script>
(function(){
const sp=window.showPage;
function mark(id){document.querySelectorAll("#navlinks a[data-page]").forEach(a=>a.classList.toggle("active",a.dataset.page===id))}
window.showPage=function(id){sp(id);mark(id==="courseDetail"?"courses":id)};
mark("home");
})();
</script>

<script>
(function(){
const KEY="altaqwa_student_app_v1";
let mem=null;
function load(){try{return JSON.parse(localStorage.getItem(KEY))||{users:{},session:null}}catch(e){return mem||{users:{},session:null}}}
let DB=load();
function save(){mem=DB;try{localStorage.setItem(KEY,JSON.stringify(DB))}catch(e){}}
const $=id=>document.getElementById(id);
const today=()=>new Date().toISOString().slice(0,10);
const ICON={course:'<path d="M6 3h11a1 1 0 0 1 1 1v14H7a1 1 0 0 0-1 1V3Z"/><path d="M6 19a2 2 0 0 0 2 2h10M10 8h5M10 12h5"/>',test:'<rect x="4.5" y="4.6" width="15" height="17" rx="3"/><rect x="9" y="2.6" width="6" height="3.2" rx="1.2"/><path d="M7.6 10.5l1.3 1.3 2.2-2.4M13.2 10.6h3.2M7.6 15.6l1.3 1.3 2.2-2.4M13.2 15.7h3.2"/>',coin:'<circle cx="12" cy="12" r="9"/><path d="M12 7v10M9.5 9.5c0-1 1-1.5 2.5-1.5s2.5.6 2.5 1.6c0 2.2-5 1.2-5 3.6 0 1 1 1.6 2.5 1.6s2.5-.6 2.5-1.5"/>',store:'<path d="M5 8h14l-1 12H6L5 8Z"/><path d="M9 8V6a3 3 0 0 1 6 0v2"/>',inv:'<path d="M7 3h7l4 4v14H7V3Z"/><path d="M14 3v4h4"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21a8 8 0 0 1 16 0"/>',home:'<path d="M4 11l8-7 8 7v9H4v-9Z"/>',out:'<path d="M10 4H5v16h5M15 8l4 4-4 4M19 12H9"/>',zikr:'<circle cx="12" cy="4.5" r="2"/><circle cx="18.5" cy="8.3" r="2"/><circle cx="18.5" cy="15.7" r="2"/><circle cx="12" cy="19.5" r="2"/><circle cx="5.5" cy="15.7" r="2"/><circle cx="5.5" cy="8.3" r="2"/>',live:'<rect x="3" y="6" width="12" height="12" rx="2.5"/><path d="M15 10.5l6-3.5v10l-6-3.5"/>'};
const ic=n=>'<svg viewBox="0 0 24 24">'+ICON[n]+'</svg>';
const MENU=[["overview","Overview","home"],["live","Live Class","live"],["course","My Course","course"],["test","My Test Series","test"],["zikr","Dhikr","zikr"],["store","My Store","store"],["invoice","Your Order Invoice","inv"],["profile","Your Profile","user"]];
const TASKS=[["t1","Recite 10 minutes from your lesson"],["t2","Revise yesterday’s lesson"],["t3","Learn one new dua"]];
const STORE=[["Qur’an Notes Pack","Printable notes for your course",100],["Tajweed Practice Sheets","Rules with practice exercises",60],["Dua Booklet","Daily duas with meanings",80],["Course Completion Certificate","Digital certificate of completion",250],["1-to-1 Doubt Session","20-minute session with a teacher",300]];
const QUIZ=[["How many pillars of Islam are there?",["3","5","7"],1],["Which is the first surah of the Qur’an?",["Al-Baqarah","Al-Fatihah","An-Nas"],1],["Tajweed is the science of…",["Beautifying and correcting recitation","Writing Arabic","Islamic history"],0],["Which month do Muslims fast in?",["Rajab","Shawwal","Ramadan"],2]];
let sec="overview",quiz=null;
const cur=()=>DB.session?DB.users[DB.session]:null;
const fmt=d=>{try{return new Date(d).toLocaleDateString("en-IN",{day:"numeric",month:"short",year:"numeric"})}catch(e){return d}};
function addCoins(u,n,why){u.coins+=n;u.history.unshift({t:why,c:n,d:today()});}
function streak(u){const set=new Set(u.att);let d=new Date(),n=0;if(!set.has(today()))d.setDate(d.getDate()-1);while(set.has(d.toISOString().slice(0,10))){n++;d.setDate(d.getDate()-1)}return n}
function sync(){const u=cur();document.body.classList.toggle("in",!!u);if($("navCoins"))$("navCoins").textContent=u?u.coins:0}
function fillCourses(){const sel=$("suCourse");if(sel&&typeof courses!=="undefined")sel.innerHTML=courses.map(c=>`<option>${c.name}</option>`).join("")}

/* auth */
$("signupForm").addEventListener("submit",e=>{
e.preventDefault();
const name=$("suName").value.trim(),c=$("suContact").value.trim().toLowerCase(),p=$("suPass").value,course=$("suCourse").value,err=$("suErr");
const ok=/^\S+@\S+\.\S+$/.test(c)||/^\+?\d{10,13}$/.test(c.replace(/[\s-]/g,""));
if(name.length<2)return err.textContent="Please enter your name.";
if(!ok)return err.textContent="Enter a valid phone number or email.";
if(p.length<6)return err.textContent="Password must be at least 6 characters.";
if(DB.users[c])return err.textContent="This phone/email is already registered. Please login.";
err.textContent="";
const u={name,contact:c,pass:p,course,coins:0,history:[],att:[],tasks:{},orders:[],tests:[1,2,3].map(i=>({id:i,title:course+(i<3?" – Weekly Test "+i:" – Monthly Test"),done:false})),since:today()};
addCoins(u,50,"Welcome bonus");
DB.users[c]=u;DB.session=c;save();sync();$("signupForm").reset();fillCourses();go("overview");showPage("dashboard");toast("Account created! 50 welcome coins added 🎉");
});

$("loginForm").addEventListener("submit",e=>{
e.preventDefault();
const c=$("lgContact").value.trim().toLowerCase(),p=$("lgPass").value,u=DB.users[c],err=$("lgErr");
if(!u||u.pass!==p)return err.textContent="Wrong phone/email or password.";
err.textContent="";DB.session=c;save();sync();$("loginForm").reset();go("overview");showPage("dashboard");toast("Welcome back, "+u.name.split(" ")[0]+"!");
});

function logout(){DB.session=null;save();sync();$("dSide").classList.remove("open");showPage("home");toast("You have been logged out.")}

/* dashboard */
function navHtml(){return MENU.map(m=>`<button data-sec="${m[0]}" class="${m[0]===sec?"on":""}">${ic(m[2])}${m[1]}</button>`).join("")+'<hr><button data-sec="logout">'+ic("out")+"Logout</button>"}
function go(x){sec=x;if(x!=="zikr"){zsel=null;zmode="tasbeeh"}render()}
function render(){
const u=cur();if(!u)return;
$("dNav").innerHTML=navHtml();
$("dSide").classList.remove("open");
const title=(MENU.find(m=>m[0]===sec)||[0,"Overview"])[1];
let body="";
({overview:vOverview,live:vLive,zikr:vZikr,course:vCourse,test:vTest,coins:vCoins,store:vStore,invoice:vInvoice,profile:vProfile})[sec] && (body=({overview:vOverview,live:vLive,zikr:vZikr,course:vCourse,test:vTest,coins:vCoins,store:vStore,invoice:vInvoice,profile:vProfile})[sec](u));
$("dMain").innerHTML=`<div class="dtop"><button class="dmenu" id="dMenuBtn">☰ Menu</button><h2>${sec==="overview"?"Hello, "+u.name.split(" ")[0]:title}</h2><button class="coinpill" data-sec="store" aria-label="Coins: ${u.coins}"><i class="bolt"></i><b>${u.coins}</b><svg viewBox="0 0 24 24" class="chev"><path d="M9 5l7 7-7 7"/></svg></button></div>`+body;
sync();
}

function hist(u,n){return u.history.length?u.history.slice(0,n).map(h=>`<div class="drow"><div class="grow"><b>${h.t}</b><small>${fmt(h.d)}</small></div><span class="${h.c>=0?"pos":"neg"}">${h.c>=0?"+":""}${h.c}</span></div>`).join(""):'<div class="empty">No activity yet.</div>'}
function todayBox(u){const done=u.att.includes(today()),td=u.tasks[today()]||[];return `<div class="dpanel"><h3>Today</h3><p>Mark attendance and finish tasks to earn coins.</p><div class="drow"><div class="grow"><b>Today’s attendance</b><small>+5 coins · 7-day streak bonus +20</small></div><button class="dbtn gold" data-act="att" ${done?"disabled":""}>${done?"Marked ✓":"Mark attendance"}</button></div>`+TASKS.map(t=>`<label class="tk"><input type="checkbox" data-task="${t[0]}" ${td.includes(t[0])?"checked disabled":""}><span class="grow">${t[1]}</span><span class="chip gold">+10</span></label>`).join("")+"</div>"}
function vCourse(u){const c=(typeof courses!=="undefined"?courses:[]).find(x=>x.name===u.course)||{name:u.course,desc:""},done=u.tests.filter(t=>t.done).length,pct=Math.min(100,Math.round((u.att.length*4+done*20)/1.2)/1);return `<div class="dpanel"><h3>${c.name}</h3><p>${c.desc||c.short||"Your enrolled course."}</p><div class="drow"><div class="grow"><b>Progress</b><small>Based on attendance and tests</small><div class="bar"><i style="width:${Math.min(pct,100)}%"></i></div></div><span class="chip">${Math.min(pct,100)}%</span></div><div class="drow"><div class="grow"><b>Classes attended</b></div><b>${u.att.length}</b></div><div class="drow"><div class="grow"><b>Next step</b><small>Take your next test in “My Test Series”</small></div><button class="dbtn" data-sec="test">Go to tests</button></div></div>`}
function vTest(u){return `<div class="dpanel"><h3>Test series</h3><p>Finish a test to earn <b>+15 coins</b>. Score 75% or more for a <b>+25 bonus</b>.</p>`+u.tests.map(t=>`<div class="drow"><div class="grow"><b>${t.title}</b><small>${t.done?`Score ${t.score}/${QUIZ.length} · +${t.coins} coins`:"Not attempted"}</small></div>${t.done?'<span class="chip">Done ✓</span>':`<button class="dbtn" data-start="${t.id}">Start test</button>`}</div>`).join("")+"</div>"}
function vCoins(u){return `<div class="dstats" style="grid-template-columns:1fr 1fr 1fr"><div class="dstat coin"><b>${u.coins}</b><span>Coins balance</span></div><div class="dstat"><b>${u.history.filter(h=>h.c>0).reduce((a,h)=>a+h.c,0)}</b><span>Total earned</span></div><div class="dstat"><b>${-u.history.filter(h=>h.c<0).reduce((a,h)=>a+h.c,0)}</b><span>Total spent</span></div></div><div class="dgrid"><div class="dpanel"><h3>How to earn coins</h3><p>Good effort is always rewarded.</p><div class="drow"><div class="grow"><b>Complete a daily task</b></div><span class="chip gold">+10</span></div><div class="drow"><div class="grow"><b>Daily attendance</b></div><span class="chip gold">+5</span></div><div class="drow"><div class="grow"><b>7-day attendance streak</b></div><span class="chip gold">+20</span></div><div class="drow"><div class="grow"><b>Finish a test</b></div><span class="chip gold">+15</span></div><div class="drow"><div class="grow"><b>Score 75% or more in a test</b></div><span class="chip gold">+25</span></div></div>${todayBox(u)}</div><div class="dpanel"><h3>Coin history</h3><p>Everything you earned and spent.</p>${hist(u,30)}</div>`}
function vStore(u){return `<div class="dpanel"><h3>Redeem your coins</h3><p>You have <b>🪙 ${u.coins}</b> coins.</p><div class="store">`+STORE.map((s,i)=>`<div class="sitem"><b>${s[0]}</b><small>${s[1]}</small><span class="chip gold">🪙 ${s[2]}</span><button class="dbtn ${u.coins>=s[2]?"":"ghost"}" data-buy="${i}">${u.coins>=s[2]?"Redeem":"Need "+(s[2]-u.coins)+" more"}</button></div>`).join("")+"</div></div>"}
function vInvoice(u){return `<div class="dpanel"><h3>Your orders</h3><p>Invoices for everything you redeemed.</p>`+(u.orders.length?u.orders.map(o=>`<div class="inv"><h4>Invoice ${o.no}</h4><div class="drow"><div class="grow"><b>${o.item}</b><small>${fmt(o.date)} · Billed to ${u.name}</small></div><span class="neg">−${o.cost} coins</span></div><small>Paid with coins · Status: Confirmed</small></div>`).join(""):'<div class="empty">No orders yet. Redeem something from My Store.</div>')+"</div>"}
function vProfile(u){const opts=(typeof courses!=="undefined"?courses:[]).map(c=>`<option ${c.name===u.course?"selected":""}>${c.name}</option>`).join("");return `<div class="dpanel"><h3>Your profile</h3><p>Member since ${fmt(u.since)}</p><div class="pf"><label>Full name<input id="pfName" value="${u.name.replace(/"/g,"&quot;")}"></label><label>Phone / email<input value="${u.contact}" disabled></label><label class="full">Course<select id="pfCourse">${opts}</select></label></div><div style="margin-top:16px"><button class="dbtn" data-act="save">Save changes</button></div></div>`}

/* live classes */
const LIVE_DAYS=[1,3,5],LIVE_HOUR=18,LIVE_MIN=60;
function teacherFor(u){try{const t=teachers.find(x=>x.courses.includes(u.course));return t?t.name:"Your teacher"}catch(e){return "Your teacher"}}
function classes(u){const out=[],now=new Date();for(let i=-1;i<15&&out.length<6;i++){const d=new Date(now);d.setDate(d.getDate()+i);d.setHours(LIVE_HOUR,0,0,0);if(LIVE_DAYS.includes(d.getDay())&&d.getTime()+LIVE_MIN*60000>now.getTime())out.push({start:d,title:u.course+" – Live Class",teacher:teacherFor(u)})}return out}
function status(c){const now=Date.now(),st=c.start.getTime();if(now>=st-10*60000&&now<st+LIVE_MIN*60000)return {live:true,txt:now>=st?"Live now":"Starting soon"};const m=Math.round((st-now)/60000),h=Math.floor(m/60);return {live:false,txt:m<60?"Starts in "+m+" min":h<24?"Starts in "+h+"h "+(m%60)+"m":c.start.toLocaleDateString("en-IN",{weekday:"long"})}}
const when=d=>d.toLocaleString("en-IN",{weekday:"short",day:"numeric",month:"short",hour:"numeric",minute:"2-digit"});
function liveRow(c,i,demo){const s=demo?{live:true,txt:"Demo"}:status(c);return `<div class="drow"><div class="grow"><b>${c.title}${demo?' <span class="chip gold">Demo</span>':""}</b><small>${demo?"Preview how a live class will look":when(c.start)+" · "+LIVE_MIN+" min"} · ${c.teacher}</small></div>${s.live?`<button class="dbtn gold" data-join="${demo?"demo":i}">Join class</button>`:`<span class="chip">${s.txt}</span>`}</div>`}
function vLive(u){const list=classes(u),demo={title:u.course+" – Demo Class",teacher:teacherFor(u),start:new Date()};return `<div class="dpanel"><h3>Live classes</h3><p>Your weekly live classes. Join opens 10 minutes before the start time. Joining marks your attendance (+5 coins).</p>${liveRow(demo,0,true)}${list.map((c,i)=>liveRow(c,i,false)).join("")}</div><div class="dpanel"><h3>Class timetable</h3><p>${u.course} · Monday, Wednesday, Friday · 6:00 PM</p><small style="color:#68766d">The institute will confirm exact timings and the joining link for your batch.</small></div>`}
function joinClass(u,which){const list=classes(u);const c=which==="demo"?{title:u.course+" – Demo Class",teacher:teacherFor(u)}:list[+which];if(!c)return;let msg="";
if(!u.att.includes(today())){u.att.push(today());addCoins(u,5,"Attendance: joined live class");if(streak(u)%7===0)addCoins(u,20,"7-day attendance streak bonus");msg='<p class="pos" style="font-weight:800">+5 coins for joining today!</p>';save();sync()}
$("quizOv").hidden=false;$("quizBox").innerHTML=`<span class="chip red">● LIVE</span><h3 style="margin-top:8px">${c.title}</h3><p style="margin:0 0 12px;color:#5c6b62;font-size:14px">with ${c.teacher}</p><div style="aspect-ratio:16/9;border-radius:14px;background:linear-gradient(135deg,#072C21,#14644A);color:#E3C98A;display:grid;place-items:center;text-align:center;padding:18px;font-family:Georgia,serif;font-size:18px">Live classroom will appear here once session commences</div>${msg}<div style="margin-top:14px"><button class="dbtn" data-act="leave">Leave class</button></div>`}
function vOverview(u){const nx=classes(u)[0],sx=nx?status(nx):null;
const TI={course:['#174B3B','#7DDBA5','<path d="M3 5.6c3.1-1 6.1-.8 9 1v13.2c-2.9-1.8-5.9-2-9-1V5.6Z"/><path d="M21 5.6c-3.1-1-6.1-.8-9 1v13.2c2.9-1.8 5.9-2 9-1V5.6Z"/>'],test:['#12353F','#2A62A6','<rect x="4.5" y="4.6" width="15" height="17" rx="3"/><rect x="9" y="2.6" width="6" height="3.2" rx="1.2"/><path d="M7.6 10.5l1.3 1.3 2.2-2.4M13.2 10.6h3.2M7.6 15.6l1.3 1.3 2.2-2.4M13.2 15.7h3.2"/>'],live:['#4A2220','#F4A7A0','<rect x="2.5" y="6.5" width="13" height="11" rx="3"/><path d="M15.5 10.4l6-3.4v10l-6-3.4M8.2 9.8v4.4l3.6-2.2-3.6-2.2Z"/>'],zikr:['#4B3C14','#F0C65A','<g fill="currentColor" stroke="none"><circle cx="12" cy="3.6" r="1.35"/><circle cx="15.6" cy="4.6" r="1.35"/><circle cx="18" cy="7.3" r="1.35"/><circle cx="18.4" cy="10.9" r="1.35"/><circle cx="16.6" cy="14" r="1.35"/><circle cx="8.4" cy="4.6" r="1.35"/><circle cx="6" cy="7.3" r="1.35"/><circle cx="5.6" cy="10.9" r="1.35"/><circle cx="7.4" cy="14" r="1.35"/><circle cx="12" cy="16" r="1.5"/><rect x="11.2" y="17.6" width="1.6" height="3.6" rx=".8"/><circle cx="12" cy="22" r="1.1"/></g>']};
const tiles=`<div class="qp"><div class="qpg">${[["course","My Course"],["test","My Tests"],["live","Live Class"],["zikr","Dhikr"]].map(q=>`<button class="qd" data-sec="${q[0]}"><span class="qi" style="background:${TI[q[0]][0]};color:${TI[q[0]][1]}"><svg viewBox="0 0 24 24">${TI[q[0]][2]}</svg></span><b>${q[1]}</b></button>`).join("")}</div></div>`;
const strip=nx?`<div class="dpanel" style="display:flex;align-items:center;gap:14px;flex-wrap:wrap"><div class="grow" style="flex:1;min-width:200px"><h3 style="margin:0">Next live class</h3><p style="margin:2px 0 0">${nx.title} · ${when(nx.start)} · ${nx.teacher}</p></div>${sx.live?`<button class="dbtn gold" data-join="0">Join class</button>`:`<span class="chip">${sx.txt}</span>`}</div>`:"";
return tiles}

/* zikr / tasbeeh */
const ZIKR=[["subhanallah","سُبْحَانَ ٱللَّٰهِ","SubhanAllah","Glory be to Allah",33],["alhamdulillah","ٱلْحَمْدُ لِلَّٰهِ","Alhamdulillah","All praise is for Allah",33],["allahuakbar","ٱللَّٰهُ أَكْبَرُ","Allahu Akbar","Allah is the Greatest",34],["tahleel","لَا إِلَٰهَ إِلَّا ٱللَّٰهُ","La ilaha illallah","There is no god but Allah",100],["istighfar","أَسْتَغْفِرُ ٱللَّٰهَ","Astaghfirullah","I seek forgiveness from Allah",100],["hawqala","لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِٱللَّٰهِ","La hawla wa la quwwata illa billah","There is no power or strength except with Allah",100],["durood","صَلَّى ٱللَّٰهُ عَلَيْهِ وَسَلَّمَ","Durood Shareef","Sallallahu alaihi wasallam",100]];
let zsel=null;
function zc(u){if(!u.z||u.z.date!==today())u.z={date:today(),c:{}};return u.z.c}
function zring(n,t){return Math.min(100,Math.round(n/t*100))}
const ZP=["subhanallah","alhamdulillah","allahuakbar","istighfar","durood"];let zmode="tasbeeh";
const dsum=(u,pre)=>Object.entries((u.dur&&u.dur.days)||{}).reduce((a,[k,v])=>a+(!pre||k.startsWith(pre)?v:0),0);

function vZikr(u){
const tabs=`<div class="dktabs"><button class="${zmode==="tasbeeh"?"on":""}" data-zmode="tasbeeh">Tasbeeh</button><button class="${zmode==="durood"?"on":""}" data-zmode="durood">Durood Participation</button></div>`;
if(zmode==="durood"){
const d=new Date().toLocaleDateString("en-GB",{weekday:"short",day:"numeric",month:"short"}).replace(",","").toUpperCase();
return `<div class="dk">${tabs}<div class="dkgold"><small>TODAY · ${d}</small><b>${dsum(u,today())}</b><span>Durood Shareef recited today</span></div><div class="dkbox"><p>How many Durood Shareef did you recite today?</p><div class="dkrow"><input id="dInput" type="number" inputmode="numeric" min="1" placeholder="e.g. 500"><button class="dksub" data-dsub="1">Submit</button></div><div class="dkchips">${[100,500,1000,5000].map(x=>`<button class="dkp" data-dchip="${x}">${x}</button>`).join("")}</div></div><div class="dkstats"><div><small>THIS MONTH</small><b>${dsum(u,today().slice(0,7))}</b></div><div><small>ALL TIME</small><b>${dsum(u)}</b></div></div></div>`}
const c=zc(u),id=zsel&&ZP.includes(zsel)?zsel:ZP[0],z=ZIKR.find(x=>x[0]===id),t=u.z.t||0,n=c[id]||0;
return `<div class="dk">${tabs}<div class="dkpills">`+ZP.map(k=>{const x=ZIKR.find(q=>q[0]===k);return `<button class="dkp ${k===id?"on":""}" data-zikr="${k}">${x[2]}</button>`}).join("")+`</div><div class="dkar">${z[1]}</div><div class="dkring" id="zRing" style="--p:${t?zring(n,t):0}"><button class="dktap" data-ztap="${id}" aria-label="Tap to count"><small id="zLbl">${t?"OF "+t:"COUNT"}</small><b id="zCount">${n}</b></button></div><div class="dkdone" id="zDone">${t&&n>=t?"Completed ✓":"&nbsp;"}</div><div class="dktargets">`+[[0,"No limit"],[33,"33"],[99,"99"],[100,"100"]].map(x=>`<button class="dkp ${x[0]===t?"on":""}" data-ztarget="${x[0]}">${x[1]}</button>`).join("")+`</div><button class="dkreset" data-act="zreset">Reset</button><div class="dktotal">Total today and before: <b id="zTot">${u.zTotal||0}</b></div></div>`}

function zTap(u,id){const t=(zc(u),u.z.t||0),c=zc(u);c[id]=(c[id]||0)+1;u.zTotal=(u.zTotal||0)+1;const n=c[id];save();try{navigator.vibrate&&navigator.vibrate(t&&n===t?[40,40,40]:10)}catch(e){}
if($("zCount")){$("zCount").textContent=n;$("zTot").textContent=u.zTotal;$("zRing").style.setProperty("--p",t?zring(n,t):0);$("zDone").textContent=t&&n>=t?"Completed ✓":"\u00a0"}}
function duroodSubmit(u){const v=Math.floor(+($("dInput").value||0));if(!(v>=1))return toast("Please enter a number.");if(v>10000000)return toast("That number looks too large.");u.dur=u.dur||{days:{}};u.dur.days[today()]=(u.dur.days[today()]||0)+v;save();render();toast("Durood recorded: "+v+". JazakAllah khair!")}

/* quiz */
function startQuiz(id){quiz={id:+id,i:0,score:0};qShow()}
function qShow(){const q=QUIZ[quiz.i];$("quizOv").hidden=false;$("quizBox").innerHTML=`<small>Question ${quiz.i+1} of ${QUIZ.length}</small><h3>${q[0]}</h3>`+q[1].map((o,k)=>`<button class="opt" data-ans="${k}">${o}</button>`).join("")+'<div style="margin-top:14px"><button class="dbtn ghost" data-act="qclose">Cancel</button></div>'}
function qAnswer(k){if(k===QUIZ[quiz.i][2])quiz.score++;quiz.i++;if(quiz.i<QUIZ.length)return qShow();const u=cur(),t=u.tests.find(x=>x.id===quiz.id),pct=quiz.score/QUIZ.length*100;let c=15;if(pct>=75){c+=25}
t.done=true;t.score=quiz.score;t.coins=c;addCoins(u,15,"Test completed: "+t.title);if(pct>=75)addCoins(u,25,"Bonus: scored "+Math.round(pct)+"%");save();$("quizBox").innerHTML=`<h3>${pct>=75?"Great job! 🎉":"Test completed"}</h3><p>You scored <b>${quiz.score}/${QUIZ.length}</b> and earned <b class="pos">+${c} coins</b>.</p><button class="dbtn" data-act="qdone">Back to dashboard</button>`}

/* events */
document.addEventListener("click",e=>{
const t=e.target;
if(t.closest("#dClose")){$("dSide").classList.remove("open");return}
if(t.closest("#dMenuBtn")){$("dSide").classList.add("open");return}
const s=t.closest("[data-sec]");if(s&&$("dashboard").contains(s)){if(s.dataset.sec==="logout")return logout();return go(s.dataset.sec)}
const u=cur();if(!u)return;
const tg=t.closest("[data-ztarget]");if(tg){zc(u);u.z.t=+tg.dataset.ztarget;save();return render()}
const zm=t.closest("[data-zmode]");if(zm){zmode=zm.dataset.zmode;return render()}
const dc=t.closest("[data-dchip]");if(dc){const el=$("dInput");if(el){el.value=dc.dataset.dchip;el.focus()}return}
if(t.closest("[data-dsub]"))return duroodSubmit(u);
const zo=t.closest("[data-zikr]");if(zo){zsel=zo.dataset.zikr;return render()}
const zt=t.closest("[data-ztap]");if(zt)return zTap(zt.dataset.ztap);
const jn=t.closest("[data-join]");if(jn)return joinClass(u,jn.dataset.join);
const st=t.closest("[data-start]");if(st)return startQuiz(st.dataset.start);
const a=t.closest("[data-ans]");if(a)return qAnswer(+a.dataset.ans);
const b=t.closest("[data-buy]");if(b){const it=STORE[+b.dataset.buy];if(u.coins<it[2])return toast("Not enough coins yet.");addCoins(u,-it[2],"Redeemed: "+it[0]);u.orders.unshift({no:"ALT-"+(1000+u.orders.length+1),item:it[0],cost:it[2],date:today()});save();render();return toast("Redeemed! See it in Your Order Invoice.")}
const act=t.closest("[data-act]");if(!act)return;const k=act.dataset.act;
if(k==="att"&&!u.att.includes(today())){u.att.push(today());addCoins(u,5,"Attendance marked");if(streak(u)%7===0)addCoins(u,20,"7-day attendance streak bonus");save();render();toast("+5 coins for attendance!")}
if(k==="save"){const n=$("pfName").value.trim();if(n.length<2)return toast("Please enter your name.");u.name=n;u.course=$("pfCourse").value;save();render();toast("Profile saved.")}
if(k==="zback"){zsel=null;return render()}
if(k==="zreset"){zc(u)[zsel||ZIKR[0][0]]=0;save();return render()}
if(k==="znext"){const i=ZIKR.findIndex(x=>x[0]===zsel);zsel=ZIKR[(i+1)%ZIKR.length][0];return render()}
if(k==="leave"){$("quizOv").hidden=true;render();return}
if(k==="qclose"||k==="qdone"){$("quizOv").hidden=true;quiz=null;render()}
});

document.addEventListener("change",e=>{
const c=e.target.closest("[data-task]");if(!c)return;const u=cur();if(!u)return;const d=today();
u.tasks[d]=u.tasks[d]||[];if(!u.tasks[d].includes(c.dataset.task)){u.tasks[d].push(c.dataset.task);addCoins(u,10,"Task completed");save();render();toast("+10 coins for completing a task!")}
});

setInterval(()=>{if(sec==="live"&&cur()&&$("dashboard").classList.contains("active")&&$("quizOv").hidden)render()},30000);
document.addEventListener("keydown",e=>{if(e.key==="Enter"&&e.target&&e.target.id==="dInput"){const u=cur();if(u)duroodSubmit(u)}});

/* routing guard */
const base=window.showPage;
window.showPage=function(id){
if(id==="dashboard"&&!cur())id="login";
if((id==="login"||id==="signup")&&cur())id="dashboard";
base(id);
if(id==="dashboard")render();
document.querySelectorAll("#navlinks a[data-page]").forEach(a=>a.classList.toggle("active",a.dataset.page===(id==="courseDetail"?"courses":id)));
};

fillCourses();
sync();
if(location.hash==="#dashboard"||location.hash==="#login"||location.hash==="#signup"||location.hash==="#courses"||location.hash==="#teachers"||location.hash==="#admissions"||location.hash==="#contact")showPage(location.hash.slice(1));
})();
</script>
</body>
</html>